import random
from collections import defaultdict, Counter

def dinucleotide_shuffle(sequence):
    if len(sequence) < 2:
        return sequence
    adj = defaultdict(list)
    for i in range(len(sequence) - 1):
        adj[sequence[i]].append(sequence[i+1])
    last_edges = {}
    for i in range(len(sequence) - 2, -1, -1):
        char = sequence[i]
        if char not in last_edges:
            target = sequence[i+1]
            last_edges[char] = target
            adj[char].remove(target)
    for char in adj:
        random.shuffle(adj[char])
    new_seq = [sequence[0]]
    current = sequence[0]
    for _ in range(len(sequence) - 1):
        if adj[current]:
            next_char = adj[current].pop()
        else:
            next_char = last_edges.get(current)
            if next_char is None:
                return dinucleotide_shuffle(sequence)
        new_seq.append(next_char)
        current = next_char
    return ''.join(new_seq)

def get_dinuc_counts(seq):
    return Counter(seq[i:i+2] for i in range(len(seq)-1))

test_seq = 'GATTACAGATTACAGATTACA'
shuffled = dinucleotide_shuffle(test_seq)
c1 = get_dinuc_counts(test_seq)
c2 = get_dinuc_counts(shuffled)
print('Original:', test_seq)
print('Shuffled:', shuffled)
print('Preserved:', c1 == c2)
"
